/* Design tokens (docs/process/ui-design.md, Direction A "Ledger" + bigger verdict).
   The only file that holds raw colours, sizes and shadows. Light on :root, dark via prefers-color-scheme. */

:root {
  color-scheme: light;

  /* Colour — light */
  --color-bg: #F5F3EE;
  --color-surface: #FFFFFF;
  --color-text: #1B1F24;
  --color-muted: #5A6069;
  --color-accent: #1F4E79;
  --color-accent-tint: #E9EFF6;
  --color-border: #DDD8CD;
  --color-field-border: #8A9099;
  --color-field-border-hover: #5A6069;
  --color-focus: #1F4E79;
  --color-pass: #1D6B3A;
  --color-pass-tint: #E6F2E9;
  --color-fail: #A8322D;
  --color-fail-tint: #FBE9E7;
  --color-error: #A8322D;
  --shadow-card: 0 1px 2px rgba(27, 31, 36, 0.06), 0 8px 24px rgba(27, 31, 36, 0.06);

  /* Type */
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --text-xs: 12px;
  --text-sm: 13px;
  --text-base: 15px;
  --text-md: 17px;
  --text-lg: 20px;
  --text-verdict: 40px;
  --text-score: 64px;
  --text-score-unit: 0.5em;
  --weight-light: 300;
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --leading-none: 1;
  --leading-heading: 1.25;
  --leading-tight: 1.4;
  --leading-normal: 1.5;
  --tracking-eyebrow: 0.12em;
  --tracking-score: -0.03em;
  --tracking-verdict: -0.01em;
  --tracking-none: 0;
  --score-unit-gap: 0.04em;

  /* Spacing (4 px base) */
  --space-0: 0;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;

  /* Sizes */
  --control-h: 44px;
  --icon-sm: 16px;
  --icon-verdict: 40px;
  --icon-glyph-scale: 70%;
  --icon-stroke-alert: 1.8;
  --icon-stroke-verdict: 3.2;
  --card-max: 520px;
  --input-max-wide: 240px;
  --border-w: 1px;
  --kbd-border-bottom-w: 2px;
  --focus-w: 2px;
  --focus-offset: 2px;

  /* Radii */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-round: 50%;

  /* Motion */
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --ease-out: cubic-bezier(0.2, 0, 0, 1);

  /* Layout — narrow (< 600 px) */
  --page-pad-top: var(--space-6);
  --page-pad-x: var(--space-4);
  --page-pad-bottom: var(--space-8);
  --card-pad-top: var(--space-6);
  --card-pad-x: var(--space-5);
  --card-pad-bottom: var(--space-6);
  --field-gap: var(--space-3);
  --error-slot-lines: 2;
  --error-slot-h: calc(var(--error-slot-lines) * var(--text-sm) * var(--leading-tight));
  --input-max: none;
  --result-min-h: 196px;
}

/* Layout — wide (≥ 600 px): one breakpoint; 768 and 1280 show the same card. */
@media (min-width: 600px) {
  :root {
    --page-pad-top: var(--space-12);
    --page-pad-x: var(--space-10);
    --page-pad-bottom: var(--space-12);
    --card-pad-top: var(--space-8);
    --card-pad-x: var(--space-10);
    --card-pad-bottom: var(--space-10);
    --field-gap: var(--space-4);
    --error-slot-lines: 1;
    --input-max: var(--input-max-wide);
    --result-min-h: 112px;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;

    /* Colour — dark */
    --color-bg: #111316;
    --color-surface: #1B1E23;
    --color-text: #ECEAE4;
    --color-muted: #A4A9B1;
    --color-accent: #8EB9E8;
    --color-accent-tint: #22303F;
    --color-border: #353A42;
    --color-field-border: #6E747E;
    --color-field-border-hover: #A4A9B1;
    --color-focus: #8EB9E8;
    --color-pass: #6FCF97;
    --color-pass-tint: #16301F;
    --color-fail: #F2958D;
    --color-fail-tint: #3A1E1C;
    --color-error: #F2958D;
    --shadow-card: 0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px rgba(0, 0, 0, 0.3);
  }
}
/* Reset, page and shared utilities. Values come from tokens.css only. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: var(--space-0);
  min-height: 100vh;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  -webkit-font-smoothing: antialiased;
}

h1,
p {
  margin: var(--space-0);
}

button,
input {
  font: inherit;
}

.app {
  padding: var(--page-pad-top) var(--page-pad-x) var(--page-pad-bottom);
}

/* Visually hidden but read by screen readers (M-37, status node). */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
/* Components and their states (docs/process/ui-design.md §Components and states). Tokens only. */

/* ---- Card ---- */
.card {
  max-width: var(--card-max);
  margin: var(--space-0) auto;
  padding: var(--card-pad-top) var(--card-pad-x) var(--card-pad-bottom);
  background: var(--color-surface);
  border: var(--border-w) solid var(--color-border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
}

.eyebrow {
  font-size: var(--text-xs);
  line-height: var(--leading-tight);
  font-weight: var(--weight-semibold);
  letter-spacing: var(--tracking-eyebrow);
  text-transform: uppercase;
  color: var(--color-muted);
}

.title {
  margin-top: var(--space-1);
  font-size: var(--text-lg);
  line-height: var(--leading-heading);
  font-weight: var(--weight-semibold);
}

.sub {
  margin: var(--space-1) var(--space-0) var(--space-6);
  font-size: var(--text-sm);
  line-height: var(--leading-tight);
  font-weight: var(--weight-regular);
  color: var(--color-muted);
}

/* ---- Fields: stacked at every width ---- */
.fields {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.label {
  display: block;
  margin-bottom: var(--space-2);
  font-size: var(--text-sm);
  line-height: var(--leading-tight);
  font-weight: var(--weight-medium);
  color: var(--color-muted);
}

/* Text input — default / filled (same look) */
.input {
  display: block;
  width: 100%;
  max-width: var(--input-max);
  height: var(--control-h);
  margin: var(--space-0);
  padding: var(--space-0) var(--space-3);
  font-size: var(--text-md);
  font-variant-numeric: tabular-nums;
  color: var(--color-text);
  background: var(--color-surface);
  border: var(--border-w) solid var(--color-field-border);
  border-radius: var(--radius-sm);
  transition:
    border-color var(--duration-fast) var(--ease-out),
    box-shadow var(--duration-fast) var(--ease-out);
}

/* hover */
.input:hover {
  border-color: var(--color-field-border-hover);
}

/* focus-visible: inputs always match :focus-visible, so the ring shows on mouse focus too */
.input:focus {
  outline: none;
}

.input:focus-visible {
  outline: var(--focus-w) solid var(--color-focus);
  outline-offset: var(--focus-offset);
}

/* error: thicker look without a size change; set by aria-invalid (or the class) */
.input[aria-invalid="true"],
.input--error {
  border-color: var(--color-error);
  box-shadow: inset 0 0 0 var(--border-w) var(--color-error);
}

/* Pass mark "%" suffix inside the input */
.input-wrap {
  position: relative;
  max-width: var(--input-max);
}

.input-wrap .input {
  padding-right: var(--space-8);
}

.suffix {
  position: absolute;
  right: var(--space-3);
  top: 50%;
  transform: translateY(-50%);
  font-size: var(--text-base);
  line-height: var(--leading-none);
  color: var(--color-muted);
  pointer-events: none;
}

/* Inline error slot: always present, keeps its height when empty */
.field-error {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  min-height: var(--error-slot-h);
  margin: var(--space-1) var(--space-0) var(--field-gap);
  font-size: var(--text-sm);
  line-height: var(--leading-tight);
  font-weight: var(--weight-medium);
  color: var(--color-error);
}

.alert-icon {
  flex: none;
  width: var(--icon-sm);
  height: var(--icon-sm);
  margin-top: calc((var(--text-sm) * var(--leading-tight) - var(--icon-sm)) / 2);
  fill: var(--color-error);
}

.alert-icon .alert-mark {
  fill: none;
  stroke: var(--color-surface);
  stroke-width: var(--icon-stroke-alert);
  stroke-linecap: round;
}

.alert-icon .alert-dot {
  fill: var(--color-surface);
}

/* ---- Divider ---- */
.rule {
  margin: var(--space-2) var(--space-0) var(--space-5);
  border: 0;
  border-top: var(--border-w) solid var(--color-border);
}

/* ---- Result area: reserved height so nothing below moves ---- */
.result-body {
  margin-top: var(--space-2);
  min-height: var(--result-min-h);
}

/* idle (M-1) and error (M-3) message */
.result-msg {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-muted);
}

.result-msg .alert-icon {
  margin-top: calc((var(--text-base) * var(--leading-normal) - var(--icon-sm)) / 2);
}

/* result: score + verdict (+ gap line); verdict under the score when narrow, beside it when wide */
.outcome {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: "score" "verdict" "gap";
  row-gap: var(--space-3);
  justify-items: start;
}

@media (min-width: 600px) {
  .outcome {
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas: "score verdict" "gap gap";
    column-gap: var(--space-6);
    align-items: center;
  }
}

.score {
  grid-area: score;
  font-size: var(--text-score);
  line-height: var(--leading-none);
  font-weight: var(--weight-light);
  letter-spacing: var(--tracking-score);
  font-variant-numeric: tabular-nums lining-nums;
  white-space: nowrap;
}

.score-unit {
  margin-left: var(--score-unit-gap);
  font-size: var(--text-score-unit);
  letter-spacing: var(--tracking-none);
  color: var(--color-muted);
}

/* Verdict block: word + tick/cross disc, never colour alone, never a pill */
.verdict {
  grid-area: verdict;
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-5) var(--space-2) var(--space-2);
  border: var(--border-w) solid currentColor;
  border-radius: var(--radius-md);
  font-size: var(--text-verdict);
  line-height: var(--leading-none);
  font-weight: var(--weight-semibold);
  letter-spacing: var(--tracking-verdict);
}

.verdict--pass {
  color: var(--color-pass);
  background: var(--color-pass-tint);
}

.verdict--fail {
  color: var(--color-fail);
  background: var(--color-fail-tint);
}

.verdict-disc {
  display: inline-grid;
  flex: none;
  place-items: center;
  width: var(--icon-verdict);
  height: var(--icon-verdict);
  border-radius: var(--radius-round);
  background: currentColor;
}

.verdict-disc svg {
  width: var(--icon-glyph-scale);
  height: var(--icon-glyph-scale);
}

.verdict-disc .i-stroke {
  fill: none;
  stroke: var(--color-surface);
  stroke-width: var(--icon-stroke-verdict);
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* pass mark empty: M-2 in the verdict slot */
.verdict-msg {
  grid-area: verdict;
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  color: var(--color-muted);
}

/* Gap line: icon is decorative, the words carry the meaning */
.gap {
  grid-area: gap;
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  font-variant-numeric: tabular-nums;
  color: var(--color-text);
}

.gap-icon {
  flex: none;
  width: var(--icon-sm);
  height: var(--icon-sm);
  margin-top: calc((var(--text-base) * var(--leading-normal) - var(--icon-sm)) / 2);
}

.gap-icon--pass {
  fill: var(--color-pass);
}

.gap-icon--fail {
  fill: var(--color-fail);
}

/* ---- Actions ---- */
.actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

/* "Next learner" — default */
.btn {
  min-width: var(--control-h);
  min-height: var(--control-h);
  padding: var(--space-0) var(--space-5);
  font-size: var(--text-base);
  font-weight: var(--weight-semibold);
  color: var(--color-accent);
  background: transparent;
  border: var(--border-w) solid var(--color-accent);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition:
    background-color var(--duration-fast) var(--ease-out),
    color var(--duration-fast) var(--ease-out);
}

/* hover */
.btn:hover {
  background: var(--color-accent-tint);
}

/* focus-visible */
.btn:focus {
  outline: none;
}

.btn:focus-visible {
  outline: var(--focus-w) solid var(--color-focus);
  outline-offset: var(--focus-offset);
}

/* active: inverted */
.btn:active {
  background: var(--color-accent);
  color: var(--color-surface);
}

.hint {
  font-size: var(--text-sm);
  line-height: var(--leading-tight);
  font-weight: var(--weight-regular);
  color: var(--color-muted);
}

kbd {
  padding: var(--space-0) var(--space-1);
  font: inherit;
  font-size: var(--text-xs);
  color: var(--color-muted);
  border: var(--border-w) solid var(--color-border);
  border-bottom-width: var(--kbd-border-bottom-w);
  border-radius: var(--radius-sm);
}

/* ---- Reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
    animation: none !important;
  }
}
<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="color-scheme" content="light dark" />
    <!-- The title text is injected from src/messages.ts (M-30) at build time; see vite.config.ts. -->
    <title>%M-30%</title>
  </head>
  <body>
    <div id="app"></div>
    <script type="module" src="./src/main.ts"></script>
  </body>
</html>

import { ESC_KEY_LABEL, MESSAGES, SCORE_UNIT } from '../messages';
import { el, svgEl } from './dom';
import type { Verdict, ViewModel } from './view-model';

export type FieldName = 'earned' | 'total' | 'pass';

export interface ShellElements {
  readonly inputs: Readonly<Record<FieldName, HTMLInputElement>>;
  readonly errors: Readonly<Record<FieldName, HTMLParagraphElement>>;
  readonly resultBody: HTMLDivElement;
  readonly status: HTMLDivElement;
  readonly nextLearner: HTMLButtonElement;
}

/** Initial values on load and after reload (technical-design.md §State model). */
export const INITIAL_VALUES: Readonly<Record<FieldName, string>> = { earned: '', total: '', pass: '70' };

const FIELD_IDS: Readonly<Record<FieldName, string>> = { earned: 'earned', total: 'total', pass: 'pass-mark' };

function createInput(field: FieldName): HTMLInputElement {
  const input = el('input', {
    class: 'input',
    id: FIELD_IDS[field],
    name: field,
    type: 'text',
    inputmode: 'decimal',
    autocomplete: 'off',
    spellcheck: 'false',
    'aria-describedby': `${FIELD_IDS[field]}-error`,
  });
  input.value = INITIAL_VALUES[field];
  return input;
}

function createErrorSlot(field: FieldName): HTMLParagraphElement {
  return el('p', { class: 'field-error', id: `${FIELD_IDS[field]}-error` });
}

function createField(
  field: FieldName,
  labelChildren: ReadonlyArray<Node | string>,
  input: HTMLInputElement,
  error: HTMLParagraphElement,
): HTMLDivElement {
  const control =
    field === 'pass'
      ? el('div', { class: 'input-wrap' }, [input, el('span', { class: 'suffix', 'aria-hidden': 'true' }, [MESSAGES['M-38']])])
      : input;
  return el('div', { class: `field field--${field}` }, [
    el('label', { class: 'label', for: FIELD_IDS[field] }, labelChildren),
    control,
    error,
  ]);
}

/** A muted message in the result body, e.g. the idle prompt M-1; no score. */
function resultMessage(text: string): HTMLParagraphElement {
  return el('p', { class: 'result-msg' }, [text]);
}

/** Tick (Pass) and cross (Fail) glyphs from the mockup, drawn on a 24 × 24 grid. */
const VERDICT_GLYPHS: Readonly<Record<Verdict, string>> = {
  pass: 'M6.5 12.5l3.8 3.8 7.4-8.3',
  fail: 'M8 8l8 8M16 8l-8 8',
};

/** Score "76.0" with the half-size muted "%" unit. */
function scoreNode(score: string): HTMLParagraphElement {
  return el('p', { class: 'score' }, [score, el('span', { class: 'score-unit' }, [SCORE_UNIT])]);
}

/** Verdict block: decorative tick/cross disc + the word, so the verdict never relies on colour alone. */
function verdictNode(verdict: Verdict, text: string): HTMLParagraphElement {
  const glyph = svgEl('svg', { viewBox: '0 0 24 24', 'aria-hidden': 'true', focusable: 'false' }, [
    svgEl('path', { class: 'i-stroke', d: VERDICT_GLYPHS[verdict] }),
  ]);
  return el('p', { class: `verdict verdict--${verdict}` }, [
    el('span', { class: 'verdict-disc' }, [glyph]),
    el('span', {}, [text]),
  ]);
}

/** Renders the result body for a view model. Displays only; never calculates. */
export function renderResult(resultBody: HTMLElement, vm: ViewModel): void {
  switch (vm.state) {
    case 'idle':
      resultBody.replaceChildren(resultMessage(vm.message));
      return;
    case 'pass-mark-empty':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [scoreNode(vm.score), el('p', { class: 'verdict-msg' }, [vm.verdictMessage])]),
      );
      return;
    case 'result':
      resultBody.replaceChildren(
        el('div', { class: 'outcome' }, [scoreNode(vm.score), verdictNode(vm.verdict, vm.verdictText)]),
      );
      return;
  }
}

/** Builds the static card once from messages.ts and mounts it into `root`. Never calculates. */
export function renderShell(root: HTMLElement): ShellElements {
  const inputs = { earned: createInput('earned'), total: createInput('total'), pass: createInput('pass') };
  const errors = { earned: createErrorSlot('earned'), total: createErrorSlot('total'), pass: createErrorSlot('pass') };

  const resultBody = el('div', { class: 'result-body' }, [resultMessage(MESSAGES['M-1'])]);
  const status = el('div', { class: 'sr-only', role: 'status', 'aria-live': 'polite', 'aria-atomic': 'true' });
  const nextLearner = el('button', { class: 'btn', type: 'button', 'aria-keyshortcuts': 'Escape' }, [MESSAGES['M-25']]);

  const hintLead = MESSAGES['M-40'].slice(0, -ESC_KEY_LABEL.length);

  const card = el('article', { class: 'card', 'aria-labelledby': 'card-title' }, [
    el('header', { class: 'card-head' }, [
      el('p', { class: 'eyebrow' }, [MESSAGES['M-31']]),
      el('h1', { class: 'title', id: 'card-title' }, [MESSAGES['M-32']]),
      el('p', { class: 'sub' }, [MESSAGES['M-33']]),
    ]),
    el('div', { class: 'fields' }, [
      createField('earned', [MESSAGES['M-34']], inputs.earned, errors.earned),
      createField('total', [MESSAGES['M-35']], inputs.total, errors.total),
      createField('pass', [MESSAGES['M-36'], el('span', { class: 'sr-only' }, [MESSAGES['M-37']])], inputs.pass, errors.pass),
    ]),
    el('hr', { class: 'rule' }),
    el('section', { class: 'result', 'aria-labelledby': 'score-label' }, [
      el('p', { class: 'eyebrow', id: 'score-label' }, [MESSAGES['M-39']]),
      resultBody,
      status,
    ]),
    el('div', { class: 'actions' }, [
      nextLearner,
      el('span', { class: 'hint' }, [hintLead, el('kbd', {}, [ESC_KEY_LABEL])]),
    ]),
  ]);

  root.replaceChildren(el('main', { class: 'app' }, [card]));
  return { inputs, errors, resultBody, status, nextLearner };
}
import { formatScore } from '../logic/format';
import { isPass, scoreTenths } from '../logic/score';
import { announcementText, MESSAGES, scoreText } from '../messages';
import { validateInputs, type RawFields } from '../validation/validate';

// Pure: raw field text → what the result area shows (technical-design.md §State model). No DOM.

export type RawInputs = RawFields;

export type Verdict = 'pass' | 'fail';

/** `announcement` is the status text for screen readers; '' means nothing to announce. */
export type ViewModel =
  | { readonly state: 'idle'; readonly message: string; readonly announcement: string }
  | {
      readonly state: 'pass-mark-empty';
      readonly score: string;
      readonly verdictMessage: string;
      readonly announcement: string;
    }
  | {
      readonly state: 'result';
      readonly score: string;
      readonly verdict: Verdict;
      readonly verdictText: string;
      readonly announcement: string;
    };

// Idle is not announced (it is announced only after Next learner, S-4).
const IDLE: ViewModel = { state: 'idle', message: MESSAGES['M-1'], announcement: '' };

/** Recomputed from the three raw strings on every input event; no stored calculation state. */
