const { chromium } = require('/opt/node22/lib/node_modules/playwright');
const fs = require('fs');
const path = require('path');

const OUT = '/tmp/claude-0/-home-user/aea11bb9-83e3-5459-94fc-a24723a2132a/scratchpad/shots';
fs.mkdirSync(OUT, { recursive: true });
const URL = 'http://localhost:4174/';
const MOCK = 'file:///home/user/Web-Calculator-fresh/sabee-khan-calculator/docs/process/design/mockup.html';

const STATES = {
  idle: null,
  pass: ['17.5', '23', '70'],
  fail: ['15.5', '23', '70'],
  boundary: ['17.49', '25', '70'],
  full: ['23', '23', '100'],
  nopass: ['17.5', '23', ''],
};

async function setField(page, id, value) {
  const loc = page.locator('#' + id);
  await loc.click();
  await page.keyboard.press('Control+A');
  await page.keyboard.press('Backspace');
  if (value) await loc.pressSequentially(value);
}

function measureScript() {
  const q = (s) => document.querySelector(s);
  const r = (el) => { if (!el) return null; const b = el.getBoundingClientRect(); return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; };
  const cs = (el, props) => { if (!el) return null; const c = getComputedStyle(el); const o = {}; for (const p of props) o[p] = c.getPropertyValue(p); return o; };
  const card = q('.card');
  return {
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    card: r(card),
    btn: r(q('.btn')),
    resultBody: r(q('.result-body')),
    outcome: r(q('.outcome')),
    score: r(q('.score')),
    scoreText: q('.score') ? q('.score').textContent : null,
    unit: r(q('.score-unit, .pct')),
    verdict: r(q('.verdict')),
    verdictMsg: r(q('.verdict-msg')),
    verdictText: q('.verdict') ? q('.verdict').textContent : null,
    disc: r(q('.verdict-disc')),
    resultMsg: q('.result-msg') ? q('.result-msg').textContent : null,
    verdictMsgText: q('.verdict-msg') ? q('.verdict-msg').textContent : null,
    gap: r(q('.gap')),
    label: r(q('.label')),
    input: r(q('.input')),
    rule: r(q('.rule')),
    eyebrowScore: r(q('.result .eyebrow')),
    errSlots: [...document.querySelectorAll('.field-error')].map((e) => r(e).h),
    scoreCS: cs(q('.score'), ['font-size', 'font-weight', 'line-height', 'letter-spacing', 'font-variant-numeric', 'color', 'font-family']),
    unitCS: cs(q('.score-unit, .pct'), ['font-size', 'color', 'margin-left', 'letter-spacing']),
    verdictCS: cs(q('.verdict'), ['font-size', 'font-weight', 'color', 'background-color', 'border-top-color', 'border-top-width', 'border-radius', 'padding', 'letter-spacing', 'line-height']),
    discCS: cs(q('.verdict-disc'), ['background-color', 'width', 'height']),
    strokeCS: cs(q('.verdict-disc .i-stroke'), ['stroke', 'stroke-width']),
    verdictMsgCS: cs(q('.verdict-msg'), ['font-size', 'color', 'line-height']),
    resultMsgCS: cs(q('.result-msg'), ['font-size', 'color']),
    surface: cs(card, ['background-color']),
    bodyBg: cs(document.body, ['background-color']),
  };
}

async function runApp(browser, width, scheme) {
  const ctx = await browser.newContext({ viewport: { width, height: 1000 }, colorScheme: scheme, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const consoleMsgs = [];
  page.on('console', (m) => consoleMsgs.push(m.type() + ': ' + m.text()));
  await page.goto(URL);
  const res = {};
  for (const [name, vals] of Object.entries(STATES)) {
    if (vals) {
      await setField(page, 'earned', '');
      await setField(page, 'total', vals[1]);
      await setField(page, 'pass-mark', vals[2]);
      await setField(page, 'earned', vals[0]); // focus ends in Marks earned (mockup (b))
    } else {
      await setField(page, 'earned', '');
      await setField(page, 'total', '');
      await setField(page, 'pass-mark', '70');
      await page.locator('#pass-mark').blur();
    }
    await page.waitForTimeout(50);
    res[name] = await page.evaluate(measureScript);
    await page.screenshot({ path: path.join(OUT, `app-${name}-${width}-${scheme}.png`), fullPage: true });
  }
  // keyboard focus ring check on the button and inputs
  await page.locator('#earned').focus();
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Tab');
  const ring = [];
  for (let i = 0; i < 4; i++) {
    ring.push(await page.evaluate(() => {
      const a = document.activeElement; const c = getComputedStyle(a);
      return { id: a.id || a.className, outline: c.outlineStyle + ' ' + c.outlineWidth + ' ' + c.outlineColor, offset: c.outlineOffset, fv: a.matches(':focus-visible') };
    }));
    if (i === 3) await page.screenshot({ path: path.join(OUT, `app-focusbtn-${width}-${scheme}.png`), fullPage: true });
    await page.keyboard.press('Tab');
  }
  res.ring = ring;
  res.console = consoleMsgs;
  await ctx.close();
  return res;
}

async function runMock(browser, width, scheme) {
  const ctx = await browser.newContext({ viewport: { width, height: 1000 }, deviceScaleFactor: 1 });
  const page = await ctx.newPage();
  const res = {};
  const map = { idle: 'desktop-idle', pass: 'desktop-pass', fail: 'desktop-fail', nopass: 'desktop-nopass' };
  for (const [name, id] of Object.entries(map)) {
    await page.goto(MOCK);
    await page.evaluate(({ id, scheme }) => {
      const idx = scheme === 'light' ? 0 : 1;
      const vp = document.querySelectorAll(`#${id} .viewport`)[idx];
      const clone = vp.cloneNode(true);
      document.body.replaceChildren(clone);
      document.body.style.margin = '0';
      document.body.style.background = 'transparent';
      clone.style.border = '0'; clone.style.borderRadius = '0'; clone.style.width = '100vw'; clone.style.minHeight = '100vh';
      // mockup marks focus with .is-focus; keep it
    }, { id, scheme });
    res[name] = await page.evaluate(measureScript);
    await page.screenshot({ path: path.join(OUT, `mock-${name}-${width}-${scheme}.png`), fullPage: true });
  }
  await ctx.close();
  return res;
}

(async () => {
  const browser = await chromium.launch();
  const all = { app: {}, mock: {} };
  for (const w of [320, 375, 768, 1280]) for (const s of ['light', 'dark']) {
    all.app[`${w}-${s}`] = await runApp(browser, w, s);
    if (w !== 320) all.mock[`${w}-${s}`] = await runMock(browser, w, s);
  }
  await browser.close();
  fs.writeFileSync(path.join(OUT, 'measure.json'), JSON.stringify(all, null, 1));
  console.log('ok');
})();

